        justify-content: center;
        align-items: center;
    }

    .hero-image {
        width: 100%;
        max-width: 1500px;
        height: auto;
        display: block;
    }

    /* =========================
       MOBILE STYLES
    ========================== */
    @media (max-width: 768px) {

        .hamburger {
